begin;
\ir helpers.psql
select plan(49);
select pg_temp.seed();
select set_config('test.application_details', '{"name":"Bar Solicitud","zone":"Ruzafa","address":"Calle de prueba 12","kind":"bar","contact":"propietario@example.com","price":"€€","lat":39.46,"lng":-0.37,"days":[1,5,6],"opens_at":"20:00","closes_at":"03:00","status":"approved","applicant_id":"00000000-0000-0000-0000-00000000000b"}',true);
select is((select count(*)::int from app.platform_admins),0,'la migración no asigna administradores');
select pg_temp.login_anon();
select throws_ok('select public.create_my_demo_venue()', '42501', null, 'sin sesión no se crea demo');
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000c');
select is(public.create_my_demo_venue()->>'error','profile_required','un menor no crea local demo');
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000a');
select set_config('test.demo_a', public.create_my_demo_venue()->>'place_id',true);
select is(public.create_my_demo_venue()->>'place_id',current_setting('test.demo_a'),'crear demo es idempotente');
select is((select count(*)::int from public.places where is_demo),1,'el dueño ve un solo local demo');
select is((select is_active from public.places where id=current_setting('test.demo_a')::uuid),false,'la demo no está publicada');
select is((select count(*)::int from public.offers where place_id=current_setting('test.demo_a')::uuid),2,'la demo incluye dos ofertas');
select lives_ok($$ update public.offers set title='Oferta editada por su dueño' where place_id=current_setting('test.demo_a')::uuid $$,'el dueño puede editar ofertas demo');
select lives_ok($$ select * from public.place_qr_credentials(current_setting('test.demo_a')::uuid) $$,'el dueño accede al QR demo');
select throws_ok($$ update public.places set is_active=true where id=current_setting('test.demo_a')::uuid $$,'42501',null,'el dueño no puede publicar su demo');
select throws_ok($$ select * from app.platform_admins $$,'42501',null,'nadie lee el registro de administradores desde el cliente');
select throws_ok($$ insert into app.platform_admins values (auth.uid()) $$,'42501',null,'nadie se convierte a sí mismo en administrador');
select is(public.venue_management_context()->>'is_admin','false','tener un local no concede administración de plataforma');
select is(public.venue_management_context()->>'approvals_enabled','false','sin administrador confirmado no hay revisión habilitada');
select is((select count(*)::int from public.tonight_places() where id=current_setting('test.demo_a')::uuid),0,'la demo no se filtra al catálogo público');
select is(public.submit_venue_application('{}')->>'error','invalid_application','rechaza campos ausentes');
select is(public.submit_venue_application(current_setting('test.application_details')::jsonb || '{"lat":91}')->>'error','invalid_application','valida coordenadas en servidor');
select is(public.submit_venue_application(current_setting('test.application_details')::jsonb || '{"days":[8]}')->>'error','invalid_application','valida días en servidor');
select set_config('test.application_a',public.submit_venue_application(current_setting('test.application_details')::jsonb)->>'application_id',true);
select is((select status from public.venue_applications where id=current_setting('test.application_a')::uuid),'pending','el cliente no puede aprobar su propia solicitud en el payload');
select is((select applicant_id from public.venue_applications where id=current_setting('test.application_a')::uuid),auth.uid(),'el solicitante es el usuario de la sesión');
select is(public.review_venue_application(current_setting('test.application_a')::uuid,true)->>'error','forbidden','el solicitante no puede aprobarse');
select throws_ok($$ update public.venue_applications set status='approved' $$,'42501',null,'tampoco se modifica el estado por la tabla');
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000b');
select is((select count(*)::int from public.places where is_demo),0,'otro usuario no ve la demo ajena');
select is((select count(*)::int from public.venue_applications),0,'otro usuario no ve datos de contacto de la solicitud');
select throws_ok($$ select * from public.place_qr_credentials(current_setting('test.demo_a')::uuid) $$,'42501',null,'otro usuario no ve las credenciales de la demo');
select is(public.cancel_venue_application(current_setting('test.application_a')::uuid)->>'error','application_unavailable','un tercero no cancela la solicitud');
select set_config('test.demo_b',public.create_my_demo_venue()->>'place_id',true);
select isnt(current_setting('test.demo_b'),current_setting('test.demo_a'),'cada cuenta recibe un demo distinto');
select throws_ok($$ insert into public.venue_applications(details) values ('{}') $$,'42501',null,'no se insertan solicitudes saltándose la validación');
do $$ begin for i in 1..3 loop perform public.submit_venue_application(current_setting('test.application_details')::jsonb); end loop; end $$;
select is(public.submit_venue_application(current_setting('test.application_details')::jsonb)->>'error','pending_limit','máximo tres pendientes por cuenta');
do $$ begin perform public.cancel_venue_application(id) from public.venue_applications where status='pending'; end $$;
do $$ begin for i in 1..2 loop perform public.submit_venue_application(current_setting('test.application_details')::jsonb); end loop; end $$;
select is(public.submit_venue_application(current_setting('test.application_details')::jsonb)->>'error','rate_limited','cancelar solicitudes no reinicia el límite diario');
reset role;
insert into app.platform_admins(user_id) values ('00000000-0000-0000-0000-00000000000d');
select pg_temp.login_as('00000000-0000-0000-0000-00000000000d');
select is(public.review_venue_application(current_setting('test.application_a')::uuid,true)->>'error','forbidden','sin correo confirmado no se aprueba aunque figure como admin');
reset role;
update auth.users set email_confirmed_at=now() where id='00000000-0000-0000-0000-00000000000d';
select pg_temp.login_as('00000000-0000-0000-0000-00000000000d');
select is(public.venue_management_context()->>'is_admin','true','el administrador designado y confirmado puede revisar');
select is(public.venue_management_context()->>'approvals_enabled','true','el estado de revisión se obtiene de la configuración real');
select set_config('test.approved_place',public.review_venue_application(current_setting('test.application_a')::uuid,true)->>'place_id',true);
select is((select status from public.venue_applications where id=current_setting('test.application_a')::uuid),'approved','el admin aprueba la solicitud');
select is(public.review_venue_application(current_setting('test.application_a')::uuid,true)->>'error','application_unavailable','una solicitud no se aprueba dos veces');
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000a');
select is((select count(*)::int from public.organizer_members m join public.places p on p.organizer_id=m.organizer_id where p.id=current_setting('test.approved_place')::uuid),1,'el solicitante recibe acceso al local aprobado');
select is((select is_active from public.places where id=current_setting('test.approved_place')::uuid),true,'solo el local aprobado se publica');
select is((select count(*)::int from public.place_opening_hours where place_id=current_setting('test.approved_place')::uuid),3,'se conservan los días de apertura solicitados');
select lives_ok($$ select * from public.place_qr_credentials(current_setting('test.approved_place')::uuid) $$,'el local aprobado tiene credenciales propias');
select set_config('test.cancelled_application',public.submit_venue_application(current_setting('test.application_details')::jsonb)->>'application_id',true);
select is(public.cancel_venue_application(current_setting('test.cancelled_application')::uuid)->>'ok','true','el solicitante cancela una pendiente');
select set_config('test.rejected_application',public.submit_venue_application(current_setting('test.application_details')::jsonb)->>'application_id',true);
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000d');
select is(public.review_venue_application(current_setting('test.rejected_application')::uuid,false,'corto')->>'error','invalid_decision','rechazar exige una explicación');
select is(public.review_venue_application(current_setting('test.rejected_application')::uuid,false,'Falta verificar la dirección.')->>'ok','true','el administrador puede rechazar con motivo');
reset role;
select pg_temp.login_as('00000000-0000-0000-0000-00000000000a');
select is((select decision_note from public.venue_applications where id=current_setting('test.rejected_application')::uuid),'Falta verificar la dirección.','el solicitante ve el motivo');
reset role;
select set_config('test.demo_organizer',(select organizer_id::text from public.places where id=current_setting('test.demo_a')::uuid),true);
-- Solo se elimina el demo, no el local real aprobado; prueba la limpieza aislada del sandbox.
delete from public.places where id=current_setting('test.demo_a')::uuid;
select is((select count(*)::int from public.organizers where id=current_setting('test.demo_organizer')::uuid),0,'el borrado del demo limpia su organizador');
select is((select count(*)::int from public.places where id=current_setting('test.approved_place')::uuid),1,'la limpieza del demo no toca el local aprobado');
select is((select count(*)::int from app.platform_admins),1,'no se han creado administradores adicionales');
select set_config('test.demo_b_organizer',(select organizer_id::text from public.places where id=current_setting('test.demo_b')::uuid),true);
select pg_temp.login_as('00000000-0000-0000-0000-00000000000b');
select lives_ok('select public.delete_my_account()','borrar la cuenta también elimina su demo sin errores de integridad');
reset role;
select is((select count(*)::int from public.places where id=current_setting('test.demo_b')::uuid),0,'no queda el local demo de la cuenta borrada');
select is((select count(*)::int from public.organizers where id=current_setting('test.demo_b_organizer')::uuid),0,'no queda el organizador demo de la cuenta borrada');
select * from finish();
rollback;
